import {configurationSkills} from './configurationSkills';

export interface ConfigurationKnowledgeCheck {
  id:string;skillId:string;serviceIds:string[];title:string;question:string;
  choices:string[];answer:number;explanation:string;sourceUrl:string;snippet?:string;
}
/** Original learning questions, not real exam questions or a completeness claim. */
function q(skillId:string,title:string,question:string,correct:string,distractors:string[],explanation:string,sourceUrl:string,snippet?:string):ConfigurationKnowledgeCheck {
  const index=configurationSkills.findIndex(s=>s.id===skillId);
  if(index<0||distractors.length!==3)throw new Error('Invalid knowledge-check definition: '+skillId);
  const answer=index%4,choices=[...distractors];choices.splice(answer,0,correct);
  return {id:'knowledge-'+skillId.replaceAll('.','-'),skillId,serviceIds:[...configurationSkills[index].serviceIds],title,question,choices,answer,explanation,sourceUrl,...(snippet?{snippet}:{})};
}

